/**
 * The words of the status pages (RFC-0043 §1.5): English is the source of truth for the keys,
 * edited here by hand; every other registered language is generated by `pnpm i18n:import` from
 * `.i18n/<locale>/status.json` (ADR-0034) and `catalog.ts` lists them all. Messages are ICU
 * MessageFormat 1 restricted to simple `{argument}`s: nothing here counts or selects, so the
 * renderer substitutes them itself and no compiler ships in the site Worker.
 */
export const en = {
  /** Before the first publish (503): the site's name may sit above it. */
  notPublished: {
    title: "Coming soon",
    body: "This site isn't published yet. Check back soon.",
  },
  /** Maintenance mode with the `maintenance` wording (503). */
  maintenance: {
    title: "We'll be back soon",
    body: "This site is down for maintenance. Thanks for your patience.",
  },
  /** Maintenance mode with the `coming-soon` wording: a published site kept private until launch (503). */
  comingSoon: {
    title: "Coming soon",
    body: "This site isn't open yet. Check back soon.",
  },
  /** The Worker serves no site, or its store cannot be read (503). */
  unavailable: {
    title: "Temporarily unavailable",
    body: "This site can't be reached right now. Please try again in a few minutes.",
  },
  /** A render failure (500); the page shows a reference id a visitor can quote. */
  error: {
    title: "Something went wrong",
    body: "This page couldn't be shown. Please try again in a moment.",
  },
  /** An expired, forged or otherwise invalid preview link (410). */
  previewExpired: {
    title: "This preview link has expired",
    body: "Ask for a new link to see this version.",
  },
  /** When maintenance ends; {time} is a date and time in the site's time zone. */
  backBy: "Back by {time}",
  /** The error page's request id; {reference} is the id a visitor can quote to the owner. */
  reference: "Reference: {reference}",
  /** The footer of the built-in page. */
  builtWith: "Built with Cloudhal",
};

export type StatusMessages = typeof en;
